package com.campus.student.domain;
import java.time.Instant; import java.util.UUID; import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.*;
class StudentTest { @Test void normalizesStudentValuesAndRejectsInvalidValues(){ Student student=Student.create(UUID.randomUUID()," S001 "," Student One ","ONE@campus.example",UUID.randomUUID(),StudentStatus.ACTIVE,Instant.now()); assertThat(student.studentNumber()).isEqualTo("S001"); assertThat(student.fullName()).isEqualTo("Student One"); assertThat(student.email()).isEqualTo("one@campus.example"); assertThatThrownBy(()->Student.create(UUID.randomUUID(),"x","Name",null,UUID.randomUUID(),StudentStatus.ACTIVE,Instant.now())).isInstanceOf(Student.InvalidStudentException.class); assertThatThrownBy(()->Student.create(UUID.randomUUID(),"S001","Name","invalid",UUID.randomUUID(),StudentStatus.ACTIVE,Instant.now())).isInstanceOf(Student.InvalidStudentException.class); } }
